<script setup lang="ts">
import { useReportManage } from '../composables/useReportManage'
import type { ReportScopeOptions } from '../api/reportTypes'
const canManage=useReportManage()
const page=ref(1),total=ref(0)
function searchRows(){page.value=1;load()}
import { onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import client from '../api/client'
const rows=ref<any[]>([]),dialog=ref(false),saving=ref(false),form=ref<any>({}),businesses=ref<any[]>([]),monitors=ref<any[]>([])
const loading=ref(false)
async function load(){loading.value=true;try{const{data}=await client.get('/status-pages/',{params:{page:page.value,page_size:20}});rows.value=data.results||data;total.value=data.count??rows.value.length}catch{ElMessage.error('状态页加载失败')}finally{loading.value=false}}
async function options(){try{const{data}=await client.get<ReportScopeOptions>('/reports/options/');businesses.value=data.businesses;monitors.value=data.monitors}catch{ElMessage.error('作用范围选项加载失败，请重试')}}
async function open(row?:any){form.value=row?{...row}:{name:'',slug:'',description:'',access_mode:'PUBLIC',theme_color:'#0c6c79',businesses:[],monitors:[],is_enabled:true};dialog.value=true;options()}
async function save(){if(!form.value.name?.trim())return ElMessage.warning('请填写状态页名称');if(!/^[a-zA-Z0-9_-]+$/.test(form.value.slug||''))return ElMessage.warning('访问标识仅支持英文字母、数字、下划线和连字符');if(!form.value.businesses?.length&&!form.value.monitors?.length)return ElMessage.warning('至少选择一个业务或探测任务');saving.value=true;try{form.value.id?await client.patch(`/status-pages/${form.value.id}/`,form.value):await client.post('/status-pages/',form.value);ElMessage.success('状态页已保存');dialog.value=false;load()}catch(e:any){ElMessage.error(JSON.stringify(e.response?.data?.details||e.response?.data||'保存失败'))}finally{saving.value=false}}
const previewOpen=ref(false),previewLoading=ref(false),previewData=ref<any>({monitors:[]}),linkOpen=ref(false),newLink=ref('')
const labels:Record<string,string>={UP:'正常',DOWN:'故障',DEGRADED:'降级',PAUSED:'暂停',MAINTENANCE:'维护',PENDING:'待探测',UNKNOWN:'未知'}
async function rotate(row:any){try{await ElMessageBox.confirm(row.has_token?'旧令牌将立即失效，确认继续？':'生成访问令牌后才能通过链接访问。','访问令牌',{type:'warning'});const{data}=await client.post(`/status-pages/${row.id}/rotate-token/`);newLink.value=`${location.origin}/status/${row.slug}?token=${data.token}`;linkOpen.value=true;load()}catch(e:any){if(e==='cancel'||e==='close')return;ElMessage.error('生成访问令牌失败')}}
async function copyLink(){try{if(!navigator.clipboard)throw new Error('unsupported');await navigator.clipboard.writeText(newLink.value);ElMessage.success('访问链接已复制')}catch{ElMessage.warning('当前环境不支持自动复制，请选中文本框中的完整链接手动复制')}}
async function remove(row:any){try{await ElMessageBox.confirm(`确认删除“${row.name}”？`,'删除状态页',{type:'warning'});await client.delete(`/status-pages/${row.id}/`);load()}catch(e:any){if(e==='cancel'||e==='close')return;ElMessage.error('删除状态页失败')}}
async function visit(row:any){previewOpen.value=true;previewLoading.value=true;previewData.value={monitors:[]};try{previewData.value=(await client.get(`/status-pages/${row.id}/preview/`)).data}catch{ElMessage.error('状态页预览失败')}finally{previewLoading.value=false}}

onMounted(load)
</script>
<template><div class="heading"><div><h2>状态页</h2><p>面向业务方发布脱敏后的实时服务可用状态</p></div><div class="toolbar"><el-button @click="searchRows">刷新</el-button><el-button v-if="canManage" type="primary" @click="open()">新增状态页</el-button></div></div><el-card shadow="never"><el-table v-loading="loading" :data="rows" stripe><el-table-column label="状态页" min-width="220"><template #default="s"><b>{{s.row.name}}</b><small>/status/{{s.row.slug}}</small></template></el-table-column><el-table-column label="访问方式" width="130"><template #default="s"><el-tag :type="s.row.access_mode==='PUBLIC'?'success':'warning'">{{s.row.access_mode==='PUBLIC'?'公开访问':'令牌访问'}}</el-tag></template></el-table-column><el-table-column prop="monitor_count" label="展示探测" width="110"/><el-table-column label="业务范围" min-width="210"><template #default="s">{{s.row.business_names?.join('、')||s.row.monitor_names?.join('、')||'—'}}</template></el-table-column><el-table-column label="状态" width="90"><template #default="s"><el-tag :type="s.row.is_enabled?'success':'info'">{{s.row.is_enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="260"><template #default="s"><el-button link type="primary" @click="visit(s.row)">预览</el-button><el-button v-if="canManage" link type="primary" @click="open(s.row)">编辑</el-button><el-button v-if="canManage&&s.row.access_mode==='TOKEN'" link type="warning" @click="rotate(s.row)">{{s.row.has_token?'轮换令牌':'生成令牌'}}</el-button><el-button v-if="canManage" link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total, prev, pager, next" @current-change="load"/></el-card>
<el-dialog v-model="dialog" :title="form.id?'编辑状态页':'新增状态页'" width="700px"><el-form label-width="120px"><el-form-item label="名称" required><el-input v-model="form.name" placeholder="例如：核心业务服务状态"/></el-form-item><el-form-item label="访问标识" required><el-input v-model="form.slug" placeholder="例如：core-services"/></el-form-item><el-form-item label="说明"><el-input v-model="form.description" type="textarea" :rows="3"/></el-form-item><el-form-item label="访问方式"><el-radio-group v-model="form.access_mode"><el-radio value="PUBLIC">公开访问</el-radio><el-radio value="TOKEN">令牌访问</el-radio></el-radio-group></el-form-item><el-form-item label="主题色"><el-color-picker v-model="form.theme_color"/><span class="color">{{form.theme_color}}</span></el-form-item><el-form-item label="业务系统"><el-select v-model="form.businesses" multiple filterable clearable style="width:100%"><el-option v-for="x in businesses" :key="x.id" :label="x.name" :value="x.id"/></el-select><small>自动展示所选业务下全部探测任务</small></el-form-item><el-form-item label="补充探测任务"><el-select v-model="form.monitors" multiple filterable clearable style="width:100%"><el-option v-for="x in monitors" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item><el-form-item label="启用"><el-switch v-model="form.is_enabled"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog><el-dialog v-model="previewOpen" title="状态页预览（管理权限）" width="760px"><div v-loading="previewLoading"><h3>{{previewData.name}}</h3><p>{{previewData.description}}</p><el-tag>{{labels[previewData.overall_status]||'暂无数据'}}</el-tag><el-table :data="previewData.monitors"><el-table-column prop="business" label="业务"/><el-table-column prop="name" label="探测任务"/><el-table-column label="状态"><template #default="s">{{labels[s.row.status]||s.row.status}}</template></el-table-column></el-table></div><template #footer><el-button @click="previewOpen=false">关闭</el-button></template></el-dialog><el-dialog v-model="linkOpen" title="保存状态页访问链接" width="620px" @closed="newLink=''"><el-alert title="令牌仅在本次显示，请妥善保存完整链接。关闭后无法再次读取，可重新生成。" type="warning" :closable="false"/><el-input :model-value="newLink" readonly type="textarea" :rows="4" style="margin-top:16px" aria-label="状态页访问链接"/><template #footer><el-button @click="linkOpen=false">已保存，关闭</el-button><el-button type="primary" @click="copyLink">复制链接</el-button></template></el-dialog></template>
<style scoped>.heading{display:flex;justify-content:space-between;align-items:end;margin-bottom:16px}.heading h2{margin:0}.heading p{margin:5px 0 0;color:#7e8d9f}small{display:block;color:#8391a2;margin-top:4px}.color{margin-left:10px;color:#718195}</style>
